export const MAX_SNAPSHOT_BYTES = 65_536;
const SNAPSHOT_KEYS = ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function hasKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}

function integerInRange(value: unknown, min: number, max: number): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= min && value <= max;
}

function decodeSelection(value: unknown, deck: readonly number[], matched: ReadonlySet<number>): Selection | null {
  if (!isRecord(value) || typeof value.kind !== 'string') return null;
  if (value.kind === 'closed' && hasKeys(value, ['kind'])) return { kind: 'closed' };
  if (value.kind === 'one' && hasKeys(value, ['kind', 'index'])) {
    if (!integerInRange(value.index, 0, deck.length - 1) || matched.has(value.index)) return null;
    return { kind: 'one', index: value.index };
  }
  if (value.kind === 'mismatch' && hasKeys(value, ['kind', 'first', 'second', 'remainingMs'])) {
    if (!integerInRange(value.first, 0, deck.length - 1) || !integerInRange(value.second, 0, deck.length - 1)) return null;
    if (value.first === value.second || matched.has(value.first) || matched.has(value.second)) return null;
    if (deck[value.first] === deck[value.second] || !integerInRange(value.remainingMs, 1, MISMATCH_MS)) return null;
    return { kind: 'mismatch', first: value.first, second: value.second, remainingMs: value.remainingMs };
  }
  return null;
}

export function encodeSnapshot(state: GameState): string {
  const selection = state.selection.kind === 'mismatch'
    ? { ...state.selection, remainingMs: Math.max(1, Math.floor(state.selection.remainingMs)) }
    : state.selection;
  return JSON.stringify({
    version: 1,
    boardCode: state.board.code,
    matched: [...state.matched],
    selection,
    moves: Math.floor(state.moves),
    elapsedMs: Math.floor(state.elapsedMs),
    started: state.started
  });
}

export function decodeSnapshot(text: string): GameState | null {
  if (new TextEncoder().encode(text).byteLength > MAX_SNAPSHOT_BYTES) return null;
  let parsed: unknown;
  try { parsed = JSON.parse(text); } catch { return null; }
  if (!isRecord(parsed) || !hasKeys(parsed, SNAPSHOT_KEYS) || parsed.version !== 1 || typeof parsed.boardCode !== 'string') return null;
  const board = parseBoardCode(parsed.boardCode);
  if (board === null || !Array.isArray(parsed.matched)) return null;
  const matched: number[] = [];
  const indices = new Set<number>();
  const faceCounts = new Map<number, number>();
  for (const index of parsed.matched) {
    if (!integerInRange(index, 0, board.deck.length - 1) || indices.has(index)) return null;
    indices.add(index);
    matched.push(index);
    const face = board.deck[index];
    if (face === undefined) return null;
    faceCounts.set(face, (faceCounts.get(face) ?? 0) + 1);
  }
  if ([...faceCounts.values()].some((count) => count !== 2)) return null;
  if (!integerInRange(parsed.moves, 0, 999_999) || !integerInRange(parsed.elapsedMs, 0, 359_999_999) || typeof parsed.started !== 'boolean') return null;
  const selection = decodeSelection(parsed.selection, board.deck, indices);
  if (selection === null) return null;
  const complete = matched.length === board.deck.length;
  if (complete && selection.kind !== 'closed') return null;
  const matchedPairs = matched.length / 2;
  if (parsed.moves < matchedPairs + (selection.kind === 'mismatch' ? 1 : 0)) return null;
  if (!parsed.started && (parsed.moves !== 0 || parsed.elapsedMs !== 0 || matched.length !== 0 || selection.kind !== 'closed')) return null;
  if (parsed.started && parsed.moves === 0 && selection.kind !== 'one') return null;
  const state = makeGameState(board, matched, selection, parsed.moves, parsed.elapsedMs, parsed.started);
  return isWon(state) === complete ? state : null;
}
import { parseBoardCode } from './board.ts';

export const MAX_REPLAY_BYTES = 1_048_576;
export const MAX_REPLAY_ACTIONS = 10_000;

export interface ReplayAction {
  readonly atMs: number;
  readonly index: number;
}

export interface ReplayDocument {
  readonly boardCode: string;
  readonly actions: readonly ReplayAction[];
  readonly endMs: number;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function hasKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}

function safeTime(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

export function decodeReplay(text: string): ReplayDocument | null {
  if (new TextEncoder().encode(text).byteLength > MAX_REPLAY_BYTES) return null;
  let parsed: unknown;
  try { parsed = JSON.parse(text); } catch { return null; }
  if (!isRecord(parsed) || !hasKeys(parsed, ['version', 'boardCode', 'actions', 'endMs'])) return null;
  if (parsed.version !== 1 || typeof parsed.boardCode !== 'string' || !safeTime(parsed.endMs)) return null;
  const board = parseBoardCode(parsed.boardCode);
  if (board === null || !Array.isArray(parsed.actions) || parsed.actions.length > MAX_REPLAY_ACTIONS) return null;
  const actions: ReplayAction[] = [];
  let previousTime = 0;
  for (const action of parsed.actions) {
    if (!isRecord(action) || !hasKeys(action, ['atMs', 'index']) || !safeTime(action.atMs)) return null;
    if (!safeTime(action.index) || action.index >= board.deck.length || action.atMs < previousTime) return null;
    actions.push({ atMs: action.atMs, index: action.index });
    previousTime = action.atMs;
  }
  if (actions.length > 0 && parsed.endMs < previousTime) return null;
  return { boardCode: parsed.boardCode, actions, endMs: parsed.endMs };
}
