export interface StoragePort {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

const SIZE_KEY = 'neon-pairs.preferences.v1';
const BEST_KEY = 'neon-pairs.best.v1';

function browserStorage(): StoragePort | null {
  try { return window.localStorage; } catch { return null; }
}

function readJson(storage: StoragePort | null, key: string): unknown {
  if (storage === null) return null;
  try {
    const text = storage.getItem(key);
    return text === null ? null : JSON.parse(text) as unknown;
  } catch { return null; }
}

export function readPreferredSize(storage: StoragePort | null = browserStorage()): BoardSize | null {
  const value = readJson(storage, SIZE_KEY);
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
  const size = Reflect.get(value, 'size') as unknown;
  return isBoardSize(size) ? size : null;
}

export function writePreferredSize(size: BoardSize, storage: StoragePort | null = browserStorage()): void {
  try { storage?.setItem(SIZE_KEY, JSON.stringify({ size })); } catch { /* Storage is optional. */ }
}

export type BestScores = Partial<Record<BoardSize, number>>;

export function readBestScores(storage: StoragePort | null = browserStorage()): BestScores {
  const value = readJson(storage, BEST_KEY);
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return {};
  const scores: BestScores = {};
  for (const key of ['4', '6', '8', '10', '12', '14', '16']) {
    const size = Number(key);
    const score = Reflect.get(value, key) as unknown;
    if (isBoardSize(size) && typeof score === 'number' && Number.isSafeInteger(score) && score >= 0 && score <= MAX_MOVES) {
      scores[size] = score;
    }
  }
  return scores;
}

export function writeBestScores(scores: BestScores, storage: StoragePort | null = browserStorage()): void {
  try { storage?.setItem(BEST_KEY, JSON.stringify(scores)); } catch { /* Storage is optional. */ }
}

export function storeBest(size: BoardSize, moves: number, storage: StoragePort | null = browserStorage()): number | null {
  if (!Number.isSafeInteger(moves) || moves < 0 || moves > MAX_MOVES) return null;
  const scores = readBestScores(storage);
  const previous = scores[size];
  if (previous !== undefined && previous <= moves) return previous;
  scores[size] = moves;
  writeBestScores(scores, storage);
  return moves;
}
export interface ClockCursor {
  readonly lastTimeMs: number | null;
  readonly fractionalMs: number;
}

export interface ClockStep {
  readonly cursor: ClockCursor;
  readonly elapsedWholeMs: number;
}

export const EMPTY_CLOCK: ClockCursor = Object.freeze({ lastTimeMs: null, fractionalMs: 0 });

export function clockStep(cursor: ClockCursor, nowMs: number): ClockStep {
  if (!Number.isFinite(nowMs) || nowMs < 0) return { cursor, elapsedWholeMs: 0 };
  if (cursor.lastTimeMs === null) {
    return { cursor: { lastTimeMs: nowMs, fractionalMs: cursor.fractionalMs }, elapsedWholeMs: 0 };
  }
  const delta = Math.max(0, nowMs - cursor.lastTimeMs) + cursor.fractionalMs;
  const elapsedWholeMs = Math.floor(delta);
  return {
    cursor: { lastTimeMs: nowMs, fractionalMs: delta - elapsedWholeMs },
    elapsedWholeMs
  };
}

export function pauseClock(cursor: ClockCursor): ClockCursor {
  return { lastTimeMs: null, fractionalMs: cursor.fractionalMs };
}

export function formatElapsed(elapsedMs: number): string {
  const seconds = Math.floor(elapsedMs / 1000);
  const minutes = Math.floor(seconds / 60);
  return `${minutes}:${String(seconds % 60).padStart(2, '0')}`;
}

